    var rec = e.record; if (!rec || nz(rec.get("sheet")) !== DAILY) return;
    var mc = String(rec.collection().name || "");
    var ms = $app.findRecordsByFilter(mc, "sheet = '_ym_migrations'", "", 1, 0); if (!ms || !ms.length) return;
